create table users(id uuid primary key default gen_random_uuid(),username text unique not null,full_name text not null,role text not null check (role in ('admin','teacher','parent','student')),email text,phone text,password_hash text not null,must_change_password boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table login_attempts(id bigserial primary key,username text not null,ok boolean not null,at timestamptz not null default now());
create index on login_attempts(username,at);
create table school_sessions(id serial primary key,name text unique not null,is_current boolean not null default false);
create table terms(id serial primary key,session_id int references school_sessions(id),name text not null,starts date,ends date,is_current boolean not null default false);
create table classes(id serial primary key,name text unique not null,section text not null check (section in ('creche','reception','nursery','primary','after-school')));
create table students(id uuid primary key default gen_random_uuid(),user_id uuid references users(id),admission_no text unique not null,first_name text not null,last_name text not null,dob date,gender text,class_id int references classes(id),status text not null default 'active',created_at timestamptz not null default now());
create table parent_students(parent_id uuid references users(id),student_id uuid references students(id),primary key(parent_id,student_id));
create table teacher_classes(teacher_id uuid references users(id),class_id int references classes(id),term_id int references terms(id),primary key(teacher_id,class_id,term_id));
create table subjects(id serial primary key,name text unique not null,level text not null default 'both',category text,offered boolean not null default true);
create table class_subjects(class_id int references classes(id) on delete cascade,subject_id int references subjects(id) on delete cascade,primary key(class_id,subject_id));
create table teacher_assign(teacher_id uuid references users(id) on delete cascade,class_id int references classes(id) on delete cascade,subject_id int references subjects(id) on delete cascade,primary key(teacher_id,class_id,subject_id));
create table settings(key text primary key,value text not null);
create table attendance(student_id uuid references students(id) on delete cascade,day date not null,status text not null check (status in ('present','late','absent')),marked_by uuid references users(id),marked_at timestamptz not null default now(),late_entry boolean not null default false,primary key(student_id,day));
create table absence_alerts(id bigserial primary key,student_id uuid references students(id) on delete cascade,day date not null,status text not null default 'pending' check (status in ('pending','sent','dismissed')),teacher_id uuid references users(id),sent_at timestamptz,sent_by uuid references users(id),unique(student_id,day));
create table notifications(id bigserial primary key,user_id uuid references users(id) on delete cascade,title text not null,body text,created_at timestamptz not null default now());
create table events(id serial primary key,title text not null,description text,start_date date not null,end_date date not null,class_id int references classes(id),type text not null default 'event',created_at timestamptz not null default now());
insert into subjects(name,level,category,offered) values ('English Studies','primary','Core subjects',true),('Mathematics','primary','Core subjects',true),('Basic Science','both','Core subjects',true),('Computer Studies (ICT)','both','Core subjects',true),('Coding','both','Core subjects',true),('Physical and Health Education','both','Core subjects',true),('Handwriting','both','Core subjects',true),('History','primary','Core subjects',false),('Number Work','early','Early years',true),('Letter Work (Phonics)','early','Early years',true),('Rhymes and Songs','early','Early years',true),('Social Habits','early','Early years',true),('Health Habits','early','Early years',true),('Food and Nutrition','early','Early years',true),('Physical Development','early','Early years',true),('Social Norms and Values','early','Early years',false),('Social Studies','primary','National values',true),('Civic Education','both','National values',true),('Security Education','primary','National values',true),('Agricultural Science','primary','Prevocational studies',true),('Home Economics','primary','Prevocational studies',true),('Religion and National Values (RNV)','both','Religion',true),('Christian Religious Studies (CRS)','both','Religion',false),('Islamic Religious Studies (IRS)','both','Religion',false),('Yoruba Language','both','Languages',true),('French','both','Languages',true),('Arabic','primary','Languages',false),('Igbo Language','primary','Languages',false),('Hausa Language','primary','Languages',false),('Literature in English','primary','Languages',false),('Cultural and Creative Arts','both','Arts',true),('Music','both','Arts',true),('Art and Craft','both','Arts',true),('Chess','both','Sports and activities',true),('Verbal Reasoning','primary','Reasoning and exam prep',false),('Quantitative Reasoning','primary','Reasoning and exam prep',false) on conflict do nothing;
create table scores(student_id uuid references students(id) on delete cascade,subject_id int references subjects(id) on delete cascade,session text not null,term text not null,ca numeric,assignment numeric,exam numeric,primary key(student_id,subject_id,session,term));
create table report_comments(student_id uuid references students(id) on delete cascade,session text not null,term text not null,teacher_comment text,head_comment text,primary key(student_id,session,term));
create table published_results(class_id int references classes(id) on delete cascade,session text not null,term text not null,published_by uuid references users(id),published_at timestamptz not null default now(),primary key(class_id,session,term));
create table ratings(student_id uuid references students(id) on delete cascade,item text not null,session text not null,term text not null,rating smallint not null check (rating between 1 and 5),primary key(student_id,item,session,term));
create table comment_bank(id serial primary key,kind text not null check (kind in ('teacher','head')),text text not null);
insert into comment_bank(kind,text) values ('teacher','Has performed very well this term. Keep up the good work.'),('teacher','Attentive and polite in class. Should continue to read daily.'),('teacher','A fair performance. With more practice there will be improvement.'),('teacher','Needs to put in more effort and practise at home.'),('teacher','A hardworking and well-behaved pupil.'),('head','A commendable performance. Keep it up.'),('head','Good result. Aim higher next term.'),('head','More effort is needed. We believe you can do better.');
create table lesson_notes(id serial primary key,teacher_id uuid references users(id),class_id int references classes(id),subject_id int references subjects(id),session text,term text,week int,topic text not null,objectives text,previous_knowledge text,materials text,content text,evaluation text,assignment text,status text not null default 'draft' check (status in ('draft','submitted','approved','returned')),head_comment text,share boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),reviewed_by uuid references users(id),reviewed_at timestamptz);
create table homework(id serial primary key,teacher_id uuid references users(id),class_id int references classes(id),subject_id int references subjects(id),title text not null,details text,kind text not null default 'homework' check (kind in ('homework','midterm_assignment')),due_date date,created_at timestamptz not null default now());
create table daily_reports(student_id uuid references students(id) on delete cascade,day date not null,mood text,meals text,nap text,toilet text,activities text,note text,teacher_id uuid references users(id),updated_at timestamptz not null default now(),primary key(student_id,day));
create table health_records(student_id uuid primary key references students(id) on delete cascade,blood_group text,genotype text,allergies text,conditions text,medications text,emergency_name text,emergency_phone text,doctor text,updated_at timestamptz not null default now());
create table pickup_persons(id serial primary key,student_id uuid references students(id) on delete cascade,name text not null,relationship text,phone text,code text not null,active boolean not null default true,created_at timestamptz not null default now());
create table pickup_log(id bigserial primary key,student_id uuid references students(id) on delete cascade,person_id int references pickup_persons(id),released_by uuid references users(id),released_at timestamptz not null default now());
alter table students add column photo text;
create table messages(id serial primary key,sender_id uuid references users(id),title text not null,body text,audience text not null,recipients int not null default 0,created_at timestamptz not null default now());
create table comm_book(id bigserial primary key,student_id uuid references students(id) on delete cascade,author_id uuid references users(id),body text not null,created_at timestamptz not null default now());
create table timetable(class_id int references classes(id) on delete cascade,day int not null check (day between 1 and 5),period int not null check (period between 1 and 9),text text not null,primary key(class_id,day,period));
create table admissions(id serial primary key,child_name text not null,dob date,parent_name text,phone text,email text,class_id int references classes(id),status text not null default 'new' check (status in ('new','visited','admitted','declined')),notes text,created_at timestamptz not null default now());
create table transport_routes(id serial primary key,name text not null,vehicle text,driver text,driver_phone text,times text);
create table student_transport(student_id uuid primary key references students(id) on delete cascade,route_id int references transport_routes(id) on delete set null);

create table if not exists fee_structure( id serial primary key, class_id int not null references classes(id) on delete cascade, session text not null, term text not null, item text not null, amount numeric(12,2) not null check (amount>=0) );
create index if not exists fee_structure_lookup on fee_structure(class_id,session,term);
create table if not exists fee_payments( id bigserial primary key, student_id uuid not null references students(id) on delete cascade, session text not null, term text not null, amount numeric(12,2) not null check (amount>0), method text not null check (method in ('paystack','cash','transfer','pos')), reference text unique not null, status text not null default 'pending' check (status in ('pending','success','failed','review','voided')), payer_id uuid references users(id), recorded_by uuid references users(id), note text, created_at timestamptz not null default now(), paid_at timestamptz );
create index if not exists fee_payments_student on fee_payments(student_id,session,term);
create index if not exists fee_payments_payer on fee_payments(payer_id,status);
create table if not exists cbt_exams( id serial primary key, teacher_id uuid references users(id), class_id int not null references classes(id) on delete cascade, subject_id int not null references subjects(id) on delete cascade, title text not null, instructions text, duration_min int not null check (duration_min between 1 and 240), session text, term text, status text not null default 'draft' check (status in ('draft','published','closed')), show_result boolean not null default true, created_at timestamptz not null default now() );
create table if not exists cbt_questions( id serial primary key, exam_id int not null references cbt_exams(id) on delete cascade, position int not null, q text not null, a text not null, b text not null, c text, d text, answer char(1) not null check (answer in ('a','b','c','d')), marks numeric(6,2) not null default 1 check (marks>0) );
create index if not exists cbt_questions_exam on cbt_questions(exam_id,position);
create table if not exists cbt_attempts( id serial primary key, exam_id int not null references cbt_exams(id) on delete cascade, student_id uuid not null references students(id) on delete cascade, started_at timestamptz not null default now(), submitted_at timestamptz, answers jsonb not null default '{}'::jsonb, score numeric(8,2), total numeric(8,2), unique(exam_id,student_id) );
